//! The signed first-party indices and keys files compiled into this binary (SPEC.md section 8).
//! `cargo xtask embed-snapshot` fills `snapshot/` and `build.rs` embeds the files it lists, so a
//! fresh install can resolve and verify versions offline from its first run. Every copy is
//! verified at runtime exactly like a cached or downloaded one; a build without a snapshot
//! embeds nothing.

use jtm_core::indices::Snapshot;

/// The files `snapshot/snapshot.toml` lists, generated by `build.rs`.
pub(crate) static SNAPSHOT: Snapshot = include!(concat!(env!("OUT_DIR"), "/snapshot.rs"));

